# test_initialize_comp ----
## IO correctness ----
test_that("`initialize_comp()` works with correct inputs", {
  result <- initialize_comp(
    data = data,
    fleet = "fleet1",
    type = "AgeComp"
  )

  #' @description Test that `initialize_comp()` works with `AgeComp` type and returns an XPtr-backed object.
  expect_s3_class(result, "fims_module")
  expect_identical(result[["module_type"]], "age_comp")
  #' @description Test that the age-composition data in the returned object from `initialize_comp()` has the correct values.
  expect_equal(
    get_numeric_vector(result, "values"),
    data |>
      get_data() |>
      dplyr::filter(type == "age_comp", fleet == "fleet1") |>
      dplyr::mutate(
        out = observed * unlist(
          parse_data_distribution(.data$uncertainty)$size,
          use.names = FALSE
        )
      ) |>
      dplyr::pull(out)
  )
  clear()

  result <- initialize_comp(
    data = data,
    fleet = "fleet1",
    type = "LengthComp"
  )
  #' @description Test that `initialize_fims()` works with `LengthComp` type and returns an XPtr-backed object.
  expect_s3_class(result, "fims_module")
  expect_identical(result[["module_type"]], "length_comp")
  #' @description Test that the length-composition data in the returned object from `initialize_comp()` has the correct values.
  expect_equal(
    get_numeric_vector(result, "values"),
    data |>
      get_data() |>
      dplyr::filter(type == "length_comp", fleet == "fleet1") |>
      dplyr::mutate(out = observed * unlist(
        parse_data_distribution(.data$uncertainty)$size,
        use.names = FALSE
      )) |>
      dplyr::pull(out)
  )
  clear()
})

## Edge handling ----
test_that("`initialize_fims()` works with edge cases", {
  modified_log_devs <- default_parameters |>
    dplyr::filter(label == "log_devs") |>
    # change first 10 estimation_status for label of log_devs from random_effects
    # to assumed_known
    dplyr::mutate(
      estimation_status = dplyr::if_else(
        timing <= 11,
        "assumed_known",
        estimation_status
      ),
      distribution_type = dplyr::if_else(
        timing <= 11,
        NA_character_,
        distribution_type
      ),
      distribution = dplyr::if_else(
        timing <= 11,
        NA_character_,
        distribution
      )
    )

  parameters_multiple_types <- default_parameters |>
    # Remove rows where label is "log_devs" but keep the rows where label is NA
    dplyr::filter(label != "log_devs" | is.na(label)) |>
    dplyr::bind_rows(modified_log_devs)
  init_parm_default <- initialize_fims(parameters = default_parameters, data = data)
